import { access, realpath, readdir, readFile } from 'node:fs/promises'
import { resolve, relative, isAbsolute, sep } from 'node:path'
import type { ToolResult } from './contracts'

export interface Workspace { readonly root: string }

function inside(root: string, candidate: string): boolean {
  const rel = relative(root, candidate)
  return rel === '' || (!isAbsolute(rel) && !rel.startsWith(`..${sep}`) && rel !== '..')
}

async function safePath(workspace: Workspace, input: string): Promise<string> {
  const candidate = resolve(workspace.root, input)
  const root = await realpath(workspace.root)
  const actual = await realpath(candidate)
  if (!inside(root, actual)) throw new Error('path escapes workspace')
  return actual
}

export async function readFileTool(workspace: Workspace, path: string): Promise<ToolResult> {
  try { return { toolCallId: 'read_file', ok: true, output: await readFile(await safePath(workspace, path), 'utf8') } }
  catch (error) { return { toolCallId: 'read_file', ok: false, error: { code: 'read_failed', message: error instanceof Error ? error.message : 'read failed' } } }
}

export async function searchFilesTool(workspace: Workspace, needle: string): Promise<ToolResult> {
  const root = resolve(workspace.root)
  const found: string[] = []
  async function walk(dir: string): Promise<void> {
    for (const entry of await readdir(dir, { withFileTypes: true })) {
      const path = resolve(dir, entry.name)
      if (entry.name === 'node_modules' || entry.name === 'target' || entry.name === '.git') continue
      if (entry.isDirectory()) await walk(path)
      else if (entry.isFile() && (await readFile(path, 'utf8')).includes(needle)) found.push(relative(root, path))
    }
  }
  try { await access(root); await walk(root); return { toolCallId: 'search_files', ok: true, output: found.sort().join('\n') } }
  catch (error) { return { toolCallId: 'search_files', ok: false, error: { code: 'search_failed', message: error instanceof Error ? error.message : 'search failed' } } }
}
