pub trait OpenAiHttp {
    fn post<'a>(
        &'a self,
        url: &'a str,
        api_key: &'a str,
        body: serde_json::Value,
    ) -> Pin<Box<dyn Future<Output = Result<String, ToolError>> + Send + 'a>>;
}

pub async fn openai_complete<H: OpenAiHttp>(
    http: &H,
    base_url: &str,
    api_key: &str,
    model: &str,
    messages: &[Message],
    tools: &[ToolDefinition],
) -> Result<ModelTurn, ToolError> {
    let wire_messages: Vec<_> = messages.iter().map(|message| {
        if message.role == "tool" { serde_json::json!({"role":"tool","tool_call_id":message.tool_call_id,"content":message.content}) }
        else if message.role == "assistant" && !message.tool_calls.is_empty() { serde_json::json!({"role":"assistant","content":message.content,"tool_calls":message.tool_calls.iter().map(|call| serde_json::json!({"id":call.id,"type":"function","function":{"name":call.name,"arguments":call.arguments.to_string()}})).collect::<Vec<_>>()}) }
        else { serde_json::json!({"role":message.role,"content":message.content}) }
    }).collect();
    let body = serde_json::json!({ "model": model, "messages": wire_messages, "tools": tools.iter().map(|tool| serde_json::json!({"type":"function","function":{"name":tool.name,"description":tool.description,"parameters":tool.input_schema}})).collect::<Vec<_>>() });
    let response = http
        .post(
            &format!("{}/chat/completions", base_url.trim_end_matches('/')),
            api_key,
            body,
        )
        .await?;
    parse_openai_turn(&response)
}

pub fn parse_openai_turn(body: &str) -> Result<ModelTurn, ToolError> {
    let root: serde_json::Value = serde_json::from_str(body).map_err(|_| ToolError {
        code: "response_format".into(),
        message: "invalid JSON".into(),
    })?;
    let message = root
        .get("choices")
        .and_then(|v| v.as_array())
        .and_then(|a| a.first())
        .and_then(|v| v.get("message"))
        .ok_or_else(|| ToolError {
            code: "response_format".into(),
            message: "missing message".into(),
        })?;
    let content = message
        .get("content")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_owned();
    let mut calls = Vec::new();
    for call in message
        .get("tool_calls")
        .and_then(|v| v.as_array())
        .into_iter()
        .flatten()
    {
        let id = call
            .get("id")
            .and_then(|v| v.as_str())
            .filter(|v| !v.is_empty())
            .ok_or_else(|| ToolError {
                code: "response_format".into(),
                message: "tool call lacks id".into(),
            })?;
        let function = call.get("function").ok_or_else(|| ToolError {
            code: "response_format".into(),
            message: "missing tool function".into(),
        })?;
        let arguments: serde_json::Value = serde_json::from_str(
            function
                .get("arguments")
                .and_then(|v| v.as_str())
                .unwrap_or("{}"),
        )
        .map_err(|_| ToolError {
            code: "arguments_invalid".into(),
            message: "tool arguments are not JSON".into(),
        })?;
        if !arguments.is_object() {
            return Err(ToolError {
                code: "arguments_invalid".into(),
                message: "tool arguments must be an object".into(),
            });
        }
        let name = function
            .get("name")
            .and_then(|v| v.as_str())
            .filter(|v| !v.is_empty())
            .ok_or_else(|| ToolError {
                code: "response_format".into(),
                message: "tool call lacks name".into(),
            })?;
        calls.push(ToolCall {
            id: id.into(),
            name: function
                .get("name")
                .and_then(|v| v.as_str())
                .unwrap_or(name)
                .into(),
            arguments,
        });
    }
    let message = Message {
        role: "assistant".into(),
        content,
        tool_call_id: None,
        tool_calls: calls.clone(),
    };
    Ok(ModelTurn {
        message,
        tool_calls: calls,
    })
}

pub fn anthropic_request(messages: &[Message], model: &str) -> serde_json::Value {
    let system = messages
        .iter()
        .find(|m| m.role == "system")
        .map(|m| m.content.clone());
    let filtered: Vec<_> = messages.iter().filter(|m| m.role != "system").map(|m| {
        if m.role == "tool" { serde_json::json!({"role":"user","content":[{"type":"tool_result","tool_use_id":m.tool_call_id,"content":m.content}]}) }
        else if m.role == "assistant" && !m.tool_calls.is_empty() { serde_json::json!({"role":"assistant","content":[{"type":"text","text":m.content}, m.tool_calls.iter().map(|c| serde_json::json!({"type":"tool_use","id":c.id,"name":c.name,"input":c.arguments})).collect::<Vec<_>>() ]}) }
        else { serde_json::json!({"role": if m.role == "assistant" { "assistant" } else { "user" }, "content": m.content}) }
    }).collect();
    let mut request = serde_json::json!({"model": model, "max_tokens": 1024, "messages": filtered});
    if let Some(system) = system {
        request["system"] = system.into();
    }
    request
}

pub fn anthropic_response_to_message(body: &str) -> Result<Message, ToolError> {
    let value: serde_json::Value = serde_json::from_str(body).map_err(|_| ToolError {
        code: "response_format".into(),
        message: "invalid JSON".into(),
    })?;
    let text = value
        .get("content")
        .and_then(|v| v.as_array())
        .and_then(|a| {
            a.iter()
                .find(|v| v.get("type").and_then(|t| t.as_str()) == Some("text"))
        })
        .and_then(|v| v.get("text"))
        .and_then(|v| v.as_str())
        .unwrap_or("");
    if text.is_empty()
        && value
            .get("content")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .any(|b| b.get("type").and_then(|t| t.as_str()) == Some("tool_use"))
            })
            .unwrap_or(false)
    {
        return Ok(Message {
            role: "assistant".into(),
            content: String::new(),
            tool_call_id: None,
            tool_calls: Vec::new(),
        });
    }
    if text.is_empty() {
        return Err(ToolError {
            code: "response_format".into(),
            message: "Anthropic response lacks text content".into(),
        });
    }
    Ok(Message {
        role: "assistant".into(),
        content: text.into(),
        tool_call_id: None,
        tool_calls: Vec::new(),
    })
}

pub fn parse_anthropic_turn(body: &str) -> Result<ModelTurn, ToolError> {
    let value: serde_json::Value = serde_json::from_str(body).map_err(|_| ToolError {
        code: "response_format".into(),
        message: "invalid JSON".into(),
    })?;
    let blocks = value
        .get("content")
        .and_then(|v| v.as_array())
        .ok_or_else(|| ToolError {
            code: "response_format".into(),
            message: "missing content".into(),
        })?;
    let content = blocks
        .iter()
        .filter(|b| b.get("type").and_then(|t| t.as_str()) == Some("text"))
        .filter_map(|b| b.get("text").and_then(|t| t.as_str()))
        .collect::<Vec<_>>()
        .join("");
    let mut calls = Vec::new();
    for block in blocks
        .iter()
        .filter(|b| b.get("type").and_then(|t| t.as_str()) == Some("tool_use"))
    {
        calls.push(ToolCall {
            id: block
                .get("id")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .into(),
            name: block
                .get("name")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .into(),
            arguments: block
                .get("input")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({})),
        });
    }
